create extension if not exists pgcrypto;
do $$ begin create type public.app_role as enum ('employee','manager'); exception when duplicate_object then null; end $$;
do $$ begin create type public.transaction_kind as enum ('sale','expense'); exception when duplicate_object then null; end $$;
do $$ begin create type public.transaction_status as enum ('pending','awaiting_allocation','approved','rejected'); exception when duplicate_object then null; end $$;
create table if not exists public.employees (id uuid primary key default gen_random_uuid(), name text not null unique, role app_role not null default 'employee', telegram_user_id bigint unique, telegram_chat_id bigint, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.projects (id uuid primary key default gen_random_uuid(), name text not null unique, created_at timestamptz not null default now());
create table if not exists public.transactions (id uuid primary key default gen_random_uuid(), reference text not null unique, kind transaction_kind not null, employee_id uuid not null references employees(id), project_id uuid references projects(id), customer text, description text not null, category text, amount numeric(12,2) not null check(amount>0), status transaction_status not null default 'pending', proposed_split jsonb not null default '{"Richard":0,"Anastasia":0,"Jean-Claude":0}'::jsonb, approved_split jsonb, commission_pool numeric(12,2) not null default 0, commission_amounts jsonb, proposed_allocation text, approved_allocation text, source text not null default 'web', telegram_chat_id bigint, approved_by uuid references employees(id), approved_at timestamptz, sync_status text not null default 'pending', sync_error text, notification_status text not null default 'not_sent', notification_error text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.audit_logs (id bigint generated always as identity primary key, transaction_id uuid references transactions(id) on delete set null, actor_employee_id uuid references employees(id), action text not null, before_state jsonb, after_state jsonb, created_at timestamptz not null default now());
create table if not exists public.sync_runs (id uuid primary key default gen_random_uuid(), reference text not null, status text not null, attempts int not null default 0, error text, created_at timestamptz not null default now(), completed_at timestamptz);
create index if not exists transactions_status_idx on transactions(status); create index if not exists transactions_created_idx on transactions(created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists transactions_updated_at on transactions; create trigger transactions_updated_at before update on transactions for each row execute function public.set_updated_at();
insert into public.projects(name) values ('Project A'),('Project B'),('Company') on conflict do nothing;
insert into public.employees(name,role) values ('Richard','employee'),('Anastasia','employee'),('Jean-Claude','employee'),('Kevin','employee'),('Svetlana','manager') on conflict(name) do nothing;
alter table employees enable row level security; alter table projects enable row level security; alter table transactions enable row level security; alter table audit_logs enable row level security; alter table sync_runs enable row level security;
